//! More language runtime rules — one behavior per test (batch 2).

c_run_cases! {
    init_brace_single => { includes: ["<stdio.h>"], decls: "", body: "int a={7}; printf(\"%d\\n\", a); return 0;", expect: ["7"] },
    init_nested_braces => { includes: ["<stdio.h>"], decls: "", body: "int a[2][2]={{1,2},{3,4}}; printf(\"%d\\n\", a[1][1]); return 0;", expect: ["4"] },
    designated_array_init => { includes: ["<stdio.h>"], decls: "", body: "int a[5]={[2]=9}; printf(\"%d\\n\", a[2]); return 0;", expect: ["9"] },
    designated_struct_init => { includes: ["<stdio.h>"], decls: "struct S{int a,b;};", body: "struct S s={.b=3}; printf(\"%d\\n\", s.b); return 0;", expect: ["3"] },
    string_hex_escape => { includes: ["<stdio.h>"], decls: "", body: "printf(\"%c\\n\", '\\x41'); return 0;", expect: ["A"] },
    string_oct_escape => { includes: ["<stdio.h>"], decls: "", body: "printf(\"%c\\n\", '\\101'); return 0;", expect: ["A"] },
    wide_char_constant => { includes: ["<stdio.h>"], decls: "", body: "wchar_t w=L'Z'; printf(\"%lc\\n\", w); return 0;", expect: ["Z"] },
    float_suffix_f => { includes: ["<stdio.h>"], decls: "", body: "float f=2.5f; printf(\"%.1f\\n\", f); return 0;", expect: ["2.5"] },
    long_suffix_literal => { includes: ["<stdio.h>"], decls: "", body: "long v=3L; printf(\"%ld\\n\", v); return 0;", expect: ["3"] },
    unsigned_suffix_literal => { includes: ["<stdio.h>"], decls: "", body: "unsigned u=4u; printf(\"%u\\n\", u); return 0;", expect: ["4"] },
    ulong_suffix_literal => { includes: ["<stdio.h>"], decls: "", body: "unsigned long v=5UL; printf(\"%lu\\n\", v); return 0;", expect: ["5"] },
    ll_suffix_literal => { includes: ["<stdio.h>"], decls: "", body: "long long v=6LL; printf(\"%lld\\n\", v); return 0;", expect: ["6"] },
    hex_int_literal => { includes: ["<stdio.h>"], decls: "", body: "printf(\"%d\\n\", 0x10); return 0;", expect: ["16"] },
    octal_int_literal => { includes: ["<stdio.h>"], decls: "", body: "printf(\"%d\\n\", 010); return 0;", expect: ["8"] },
    binary_literal_extension => { includes: ["<stdio.h>"], decls: "", body: "printf(\"%d\\n\", 0b101); return 0;", expect: ["5"] },
    float_scientific_literal => { includes: ["<stdio.h>"], decls: "", body: "printf(\"%.0f\\n\", 1e2); return 0;", expect: ["100"] },
    double_default_promotion => { includes: ["<stdio.h>"], decls: "", body: "printf(\"%.1f\\n\", 1.0+2); return 0;", expect: ["3.0"] },
    char_promoted_in_printf => { includes: ["<stdio.h>"], decls: "", body: "printf(\"%d\\n\", 'A'); return 0;", expect: ["65"] },
    bool_from_comparison => { includes: ["<stdio.h>", "<stdbool.h>"], decls: "", body: "bool b=3>2; printf(\"%d\\n\", b); return 0;", expect: ["1"] },
    bool_not_operator => { includes: ["<stdio.h>", "<stdbool.h>"], decls: "", body: "bool b=true; printf(\"%d\\n\", !b); return 0;", expect: ["0"] },
    struct_in_function_param => { includes: ["<stdio.h>"], decls: "struct P{int v;}; int get(struct P p){return p.v;}", body: "struct P p={2}; printf(\"%d\\n\", get(p)); return 0;", expect: ["2"] },
    return_struct_value => { includes: ["<stdio.h>"], decls: "struct P{int v;}; struct P mk(void){struct P p={4}; return p;}", body: "printf(\"%d\\n\", mk().v); return 0;", expect: ["4"] },
    pointer_param_mutates_caller => { includes: ["<stdio.h>"], decls: "void bump(int *p){(*p)++;}", body: "int x=1; bump(&x); printf(\"%d\\n\", x); return 0;", expect: ["2"] },
    array_param_readonly => { includes: ["<stdio.h>"], decls: "int sum2(const int *a){return a[0]+a[1];}", body: "int a[]={2,3}; printf(\"%d\\n\", sum2(a)); return 0;", expect: ["5"] },
    function_ptr_from_address => { includes: ["<stdio.h>"], decls: "int id(int x){return x;}", body: "int (*fp)(int)=&id; printf(\"%d\\n\", fp(5)); return 0;", expect: ["5"] },
    null_ptr_compare_fn => { includes: ["<stdio.h>"], decls: "int f(int x){return x;}", body: "int (*fp)(int)=f; printf(\"%d\\n\", fp!=0); return 0;", expect: ["1"] },
    offsetof_nested => { includes: ["<stdio.h>", "<stddef.h>"], decls: "struct A{int x;}; struct B{struct A a; int y;};", body: "printf(\"%d\\n\", (int)offsetof(struct B,y)); return 0;", expect: ["4"] },
    alignof_pointer => { includes: ["<stdio.h>", "<stdalign.h>"], decls: "", body: "printf(\"%d\\n\", (int)alignof(void*)); return 0;", expect: ["8"] },
    generic_int_branch => { includes: ["<stdio.h>"], decls: "#define G(x) _Generic((x), int: 1, default: 0)", body: "printf(\"%d\\n\", G(0)); return 0;", expect: ["1"] },
    static_assert_in_function => { includes: ["<stdio.h>", "<assert.h>"], decls: "", body: "_Static_assert(1,\"\"); printf(\"1\\n\"); return 0;", expect: ["1"] },
    thread_local_write => { includes: ["<stdio.h>"], decls: "_Thread_local int tls;", body: "tls=5; printf(\"%d\\n\", tls); return 0;", expect: ["5"] },
    atomic_fetch_add_run => { includes: ["<stdio.h>", "<stdatomic.h>"], decls: "", body: "atomic_int x=1; atomic_fetch_add(&x,2); printf(\"%d\\n\", atomic_load(&x)); return 0;", expect: ["3"] },
    complex_literal_macro => { includes: ["<stdio.h>", "<complex.h>"], decls: "", body: "double complex z=1+2*I; printf(\"%.0f\\n\", creal(z)); return 0;", expect: ["1"] },
    va_start_end_macro => { includes: ["<stdio.h>", "<stdarg.h>"], decls: "int add2(int n,...){va_list ap; va_start(ap,n); int a=va_arg(ap,int); int b=va_arg(ap,int); va_end(ap); return a+b;}", body: "printf(\"%d\\n\", add2(2,3,4)); return 0;", expect: ["7"] },
    setjmp_skip_assignment => { includes: ["<stdio.h>", "<setjmp.h>"], decls: "", body: "jmp_buf env; int v=0; if(!setjmp(env)) { v=1; longjmp(env,1);} printf(\"%d\\n\", v); return 0;", expect: ["1"] },
    signal_raise_ignored => { includes: ["<stdio.h>", "<signal.h>"], decls: "", body: "signal(SIGUSR2,SIG_IGN); raise(SIGUSR2); printf(\"1\\n\"); return 0;", expect: ["1"] },
    errno_set_read => { includes: ["<stdio.h>", "<errno.h>"], decls: "", body: "errno=EINVAL; printf(\"%d\\n\", errno); return 0;", expect: ["22"] },
    time_time_null => { includes: ["<stdio.h>", "<time.h>"], decls: "", body: "printf(\"%d\\n\", time(0)>0); return 0;", expect: ["1"] },
    clock_per_second => { includes: ["<stdio.h>", "<time.h>"], decls: "", body: "printf(\"%d\\n\", CLOCKS_PER_SEC>0); return 0;", expect: ["1"] },
    regex_nomatch => { includes: ["<stdio.h>", "<regex.h>"], decls: "", body: "regex_t r; regcomp(&r,\"z\",0); int m=regexec(&r,\"a\",0,0,0); regfree(&r); printf(\"%d\\n\", m); return 0;", expect: ["1"] },
    bool_true_false_macros => { includes: ["<stdio.h>", "<stdbool.h>"], decls: "", body: "printf(\"%d %d\\n\", true, false); return 0;", expect: ["1 0"] },
    max_align_t_positive => { includes: ["<stdio.h>", "<stddef.h>"], decls: "", body: "printf(\"%d\\n\", (int)sizeof(max_align_t)>0); return 0;", expect: ["1"] },
    ptrdiff_subtract => { includes: ["<stdio.h>", "<stddef.h>"], decls: "", body: "int a[3]={0}; printf(\"%d\\n\", (int)(&a[2]-&a[0])); return 0;", expect: ["2"] },
    restrict_alias => { includes: ["<stdio.h>"], decls: "void addp(restrict int *a, restrict int *b){*a+=*b;}", body: "int x=1,y=2; addp(&x,&y); printf(\"%d\\n\", x); return 0;", expect: ["3"] },
    inline_in_same_file => { includes: ["<stdio.h>"], decls: "inline int sq(int x){return x*x;}", body: "printf(\"%d\\n\", sq(5)); return 0;", expect: ["25"] },
    noreturn_never_returns_compile_path => { includes: ["<stdio.h>", "<stdnoreturn.h>"], decls: "", body: "printf(\"1\\n\"); return 0;", expect: ["1"] },
    typeof_preserves_value => { includes: ["<stdio.h>"], decls: "", body: "int x=3; typeof(x) y=x; printf(\"%d\\n\", y); return 0;", expect: ["3"] },
    empty_for_init => { includes: ["<stdio.h>"], decls: "", body: "int i=0; for(;i<1;i++){} printf(\"%d\\n\", i); return 0;", expect: ["1"] },
    switch_char_case => { includes: ["<stdio.h>"], decls: "", body: "switch('a'){case 'a': printf(\"a\\n\"); break;} return 0;", expect: ["a"] },
    goto_backward => { includes: ["<stdio.h>"], decls: "", body: "int i=0; L: if(++i<2) goto L; printf(\"%d\\n\", i); return 0;", expect: ["2"] } }
